def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Find 4-connected components; isolated pixels are stray marks to repair.
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(comp) == 1:
                y, x = comp[0]
                neighbors = []
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (dy or dx) and 0 <= ny < h and 0 <= nx < w:
                            neighbors.append(grid[ny][nx])
                if neighbors:
                    counts = {}
                    for v in neighbors:
                        counts[v] = counts.get(v, 0) + 1
                    out[y][x] = max(counts, key=counts.get)

    return out
